/**
 * Generate responsive WebP variants for every media row and upload them to R2.
 *
 * The original object is left untouched. Variants are stored next to it as
 * `<key>@<width>.webp` (e.g. `images/psaume-91@800.webp`), which is what the
 * `srcset` generated by `mediaSrcSet()` points to. Re-encoding at quality 90
 * keeps the visual quality; only the displayed size changes.
 *
 * Usage:
 *   bun run images:optimize -- --bucket=<r2-bucket> --origin=<site-url> [--config=wrangler.jsonc]
 */
import { unlink } from "node:fs/promises";
import sharp from "sharp";

const args = new Map(
  process.argv.slice(2).map((arg) => {
    const [key, ...rest] = arg.replace(/^--/, "").split("=");
    return [key, rest.join("=")];
  }),
);

const origin = (args.get("origin") ?? "http://localhost:4321").replace(/\/$/, "");
const bucket = args.get("bucket");
const config = args.get("config") ?? "wrangler.jsonc";
const quality = Number(args.get("quality") ?? 90);
const widths = [480, 800, 1200];

if (!bucket) {
  console.error(
    "Usage: bun run images:optimize -- --bucket=<r2-bucket> --origin=<site-url> [--config=wrangler.jsonc]",
  );
  process.exit(1);
}

const query = Bun.spawnSync(
  [
    "bunx",
    "wrangler",
    "d1",
    "execute",
    "DB",
    "--remote",
    "--config",
    config,
    "--json",
    "--command",
    "SELECT r2_key FROM media",
  ],
  { stdout: "pipe", stderr: "inherit" },
);

const text = query.stdout.toString();
const rows = JSON.parse(text.slice(text.indexOf("[")))[0].results as { r2_key: string }[];

for (const row of rows) {
  const response = await fetch(`${origin}/media/${row.r2_key}/`);
  if (!response.ok) {
    console.warn(`skip ${row.r2_key}: ${response.status}`);
    continue;
  }

  const input = Buffer.from(await response.arrayBuffer());
  const metadata = await sharp(input).metadata();
  const originalWidth = metadata.width ?? 0;
  if (!originalWidth) {
    console.warn(`skip ${row.r2_key}: no width`);
    continue;
  }

  for (const width of widths) {
    if (width >= originalWidth) continue;

    const key = row.r2_key.replace(/(\.[a-z0-9]+)$/i, `@${width}$1`);
    const buffer = await sharp(input)
      .resize({ width, withoutEnlargement: true })
      .webp({ quality, effort: 6 })
      .toBuffer();
    const tmp = `/tmp/optimize-${crypto.randomUUID()}.webp`;
    await Bun.write(tmp, buffer);

    const put = Bun.spawnSync(
      [
        "bunx",
        "wrangler",
        "r2",
        "object",
        "put",
        `${bucket}/${key}`,
        `--file=${tmp}`,
        "--content-type=image/webp",
        "--config",
        config,
      ],
      { stdout: "inherit", stderr: "inherit" },
    );
    await unlink(tmp).catch(() => {});

    if (put.exitCode !== 0) {
      console.warn(`failed ${key}`);
      continue;
    }

    console.log(`${key} — ${Math.round(buffer.byteLength / 1024)} KB`);
  }
}
